-- ---------- biz_donkey ----------
DROP TABLE IF EXISTS biz_donkey;
CREATE TABLE biz_donkey (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  ear_tag_id VARCHAR(32) NOT NULL UNIQUE,
  breed VARCHAR(16),
  gender CHAR(1),
  birth_date DATE,
  org_id BIGINT,
  org_name VARCHAR(64),
  barn_no VARCHAR(16),
  status VARCHAR(16) DEFAULT 'RAISED',
  create_txid VARCHAR(40),
  photos JSON,
  create_time DATETIME
);

-- ---------- biz_donkey_event ----------
DROP TABLE IF EXISTS biz_donkey_event;
CREATE TABLE biz_donkey_event (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  donkey_id BIGINT,
  ear_tag_id VARCHAR(32),
  event_type VARCHAR(16) NOT NULL,
  event_time DATETIME,
  content VARCHAR(255),
  detail_hash VARCHAR(80),
  tx_id VARCHAR(40),
  block_no INT
);

-- ---------- biz_batch ----------
DROP TABLE IF EXISTS biz_batch;
CREATE TABLE biz_batch (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  batch_no VARCHAR(32) NOT NULL UNIQUE,
  batch_type VARCHAR(16) NOT NULL COMMENT 'SLAUGHTER/PROCESS/PRODUCT',
  parent_nos JSON,
  source_ear_tags JSON,
  org_id BIGINT,
  org_name VARCHAR(64),
  holder_org_id BIGINT,
  holder_org_name VARCHAR(64),
  product_name VARCHAR(64),
  weight_kg DECIMAL(8,1),
  produce_date DATE,
  expire_date DATE,
  cert_hash VARCHAR(80),
  status VARCHAR(16),
  create_txid VARCHAR(40),
  qc_report_uri VARCHAR(128),
  create_time DATETIME,
  KEY idx_type (batch_type),
  KEY idx_holder (holder_org_name)
);

-- ---------- biz_batch_event ----------
DROP TABLE IF EXISTS biz_batch_event;
CREATE TABLE biz_batch_event (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  batch_no VARCHAR(32) NOT NULL,
  event_type VARCHAR(16) NOT NULL,
  org_name VARCHAR(64),
  operator VARCHAR(32),
  event_time DATETIME,
  summary VARCHAR(255),
  tx_id VARCHAR(40),
  block_no INT,
  KEY idx_batch (batch_no)
);

-- ---------- biz_transport_order ----------
DROP TABLE IF EXISTS biz_transport_order;
CREATE TABLE biz_transport_order (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  transport_no VARCHAR(32) NOT NULL UNIQUE,
  batch_no VARCHAR(32),
  from_org_id BIGINT, from_org_name VARCHAR(64),
  to_org_id BIGINT, to_org_name VARCHAR(64),
  vehicle_no VARCHAR(16),
  driver_name VARCHAR(16),
  driver_phone VARCHAR(16),
  depart_time DATETIME,
  expect_arrive_time DATETIME,
  actual_arrive_time DATETIME,
  status VARCHAR(16),
  file_uri VARCHAR(128),
  file_hash VARCHAR(80),
  tx_id VARCHAR(40),
  create_time DATETIME,
  KEY idx_batch (batch_no)
);

-- ---------- biz_transport_record ----------
DROP TABLE IF EXISTS biz_transport_record;
CREATE TABLE biz_transport_record (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  order_id BIGINT,
  record_time DATETIME,
  temperature DECIMAL(4,1),
  humidity INT,
  abnormal TINYINT DEFAULT 0,
  KEY idx_order (order_id)
);

-- ---------- biz_output_record ----------
DROP TABLE IF EXISTS biz_output_record;
CREATE TABLE biz_output_record (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  batch_no VARCHAR(32),
  shop_org_id BIGINT,
  shop_org_name VARCHAR(64),
  output_time DATETIME,
  oven_no VARCHAR(16),
  chef VARCHAR(16),
  qty INT,
  used_weight DECIMAL(8,1),
  create_time DATETIME
);

-- ---------- biz_trace_code ----------
DROP TABLE IF EXISTS biz_trace_code;
CREATE TABLE biz_trace_code (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(20) NOT NULL UNIQUE,
  batch_no VARCHAR(32),
  shop_org_name VARCHAR(64),
  output_id BIGINT,
  status VARCHAR(16) DEFAULT 'BOUND',
  bind_txid VARCHAR(40),
  print_count INT DEFAULT 0,
  scan_times INT DEFAULT 0,
  create_time DATETIME,
  KEY idx_batch (batch_no)
);

-- ---------- biz_scan_log ----------
DROP TABLE IF EXISTS biz_scan_log;
CREATE TABLE biz_scan_log (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(20),
  ip VARCHAR(32),
  region VARCHAR(32),
  ua VARCHAR(32),
  scan_time DATETIME,
  risk_flag TINYINT DEFAULT 0,
  KEY idx_code (code)
);

