-- ---------- biz_alert ----------
DROP TABLE IF EXISTS biz_alert;
CREATE TABLE biz_alert (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  alert_type VARCHAR(20),
  level VARCHAR(8),
  target_type VARCHAR(16),
  target_id VARCHAR(32),
  content VARCHAR(255),
  status VARCHAR(12) DEFAULT 'OPEN',
  handler VARCHAR(32),
  handle_note VARCHAR(128),
  handle_time DATETIME,
  create_time DATETIME
);

-- ---------- biz_cert ----------
DROP TABLE IF EXISTS biz_cert;
CREATE TABLE biz_cert (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  org_id BIGINT,
  org_name VARCHAR(64),
  cert_type VARCHAR(32),
  cert_no VARCHAR(48),
  issue_date DATE,
  expire_date DATE,
  file_uri VARCHAR(128),
  file_hash VARCHAR(80),
  audit_status VARCHAR(12) DEFAULT 'NONE',
  status TINYINT DEFAULT 1
);

-- ---------- biz_inspection ----------
DROP TABLE IF EXISTS biz_inspection;
CREATE TABLE biz_inspection (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  batch_no VARCHAR(32),
  org_name VARCHAR(64),
  agency VARCHAR(64),
  items VARCHAR(128),
  result VARCHAR(8),
  report_uri VARCHAR(128),
  report_hash VARCHAR(80),
  tx_id VARCHAR(40),
  create_time DATETIME
);

