-- ---------- chain_block ----------
DROP TABLE IF EXISTS chain_block;
CREATE TABLE chain_block (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  block_no INT NOT NULL UNIQUE,
  prev_hash VARCHAR(80) NOT NULL,
  hash VARCHAR(80) NOT NULL,
  time DATETIME,
  tx_count INT DEFAULT 1,
  channel VARCHAR(32),
  tx_id VARCHAR(40) NOT NULL UNIQUE,
  op VARCHAR(48) NOT NULL,
  msp_id VARCHAR(32),
  org_name VARCHAR(64),
  payload TEXT COMMENT '原始交易载荷JSON文本(保持键序以便哈希重算)',
  KEY idx_op (op)
);

-- ---------- sys_operation_log ----------
DROP TABLE IF EXISTS sys_operation_log;
CREATE TABLE sys_operation_log (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT,
  user_name VARCHAR(32),
  module VARCHAR(16),
  operation VARCHAR(16),
  method VARCHAR(8),
  params VARCHAR(255),
  result_code INT,
  ip VARCHAR(32),
  cost_ms INT,
  create_time DATETIME
);

